CREATE TABLE IF NOT EXISTS "patients" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- First name as it appears on identity documents, because a controlled prescription is matched against them.
	"given_name" VARCHAR(100) NOT NULL,
	-- Surname.
	"family_name" VARCHAR(100) NOT NULL,
	-- Identity verification and weight-independent dosing checks.
	"date_of_birth" DATE NOT NULL,
	-- Login identity and the address the visit summary is sent to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Used for the SMS fallback when the video call drops mid-consultation.
	"phone" VARCHAR(32),
	-- State or province the patient is physically in, e.g. CA or NY. This is the field that decides which clinicians may legally see them, so it is not optional.
	"residence_region_code" VARCHAR(8) NOT NULL,
	-- IANA zone. Slots are stored as instants and rendered here; a patient who travels sees the same appointment at a different wall clock.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Registration time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "patients" IS 'The person receiving care. Residence region lives here rather than on an address record because every booking, price and licence check reads it, and a stale region is a compliance incident rather than a cosmetic bug.';
COMMENT ON COLUMN "patients"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "patients"."given_name" IS 'First name as it appears on identity documents, because a controlled prescription is matched against them.';
COMMENT ON COLUMN "patients"."family_name" IS 'Surname.';
COMMENT ON COLUMN "patients"."date_of_birth" IS 'Identity verification and weight-independent dosing checks.';
COMMENT ON COLUMN "patients"."email" IS 'Login identity and the address the visit summary is sent to.';
COMMENT ON COLUMN "patients"."phone" IS 'Used for the SMS fallback when the video call drops mid-consultation.';
COMMENT ON COLUMN "patients"."residence_region_code" IS 'State or province the patient is physically in, e.g. CA or NY. This is the field that decides which clinicians may legally see them, so it is not optional.';
COMMENT ON COLUMN "patients"."timezone" IS 'IANA zone. Slots are stored as instants and rendered here; a patient who travels sees the same appointment at a different wall clock.';
COMMENT ON COLUMN "patients"."created_at" IS 'Registration time.';

CREATE INDEX "idx_patients_region"
ON "patients" ("residence_region_code");

CREATE TABLE IF NOT EXISTS "clinicians" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Name as it appears on a prescription.
	"full_name" VARCHAR(160) NOT NULL,
	-- MD | DO | NP | PA | PSYD | RD. Determines what the clinician may prescribe.
	"credential" VARCHAR(24) NOT NULL,
	-- Clinical specialty used for matching and for the directory listing.
	"specialty" VARCHAR(80),
	-- Staff login.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Directory filter. Distinct from is_active: a full panel is not a departure.
	"is_accepting_new_patients" BOOLEAN NOT NULL DEFAULT true,
	-- False when the clinician leaves. Never deleted, because signed notes and prescriptions still point here.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Onboarding time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "clinicians" IS 'Anyone who can be named on a clinical record. A clinician row on its own confers no right to practise anywhere — that comes entirely from clinician_licences.';
COMMENT ON COLUMN "clinicians"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "clinicians"."full_name" IS 'Name as it appears on a prescription.';
COMMENT ON COLUMN "clinicians"."credential" IS 'MD | DO | NP | PA | PSYD | RD. Determines what the clinician may prescribe.';
COMMENT ON COLUMN "clinicians"."specialty" IS 'Clinical specialty used for matching and for the directory listing.';
COMMENT ON COLUMN "clinicians"."email" IS 'Staff login.';
COMMENT ON COLUMN "clinicians"."is_accepting_new_patients" IS 'Directory filter. Distinct from is_active: a full panel is not a departure.';
COMMENT ON COLUMN "clinicians"."is_active" IS 'False when the clinician leaves. Never deleted, because signed notes and prescriptions still point here.';
COMMENT ON COLUMN "clinicians"."created_at" IS 'Onboarding time.';

CREATE TABLE IF NOT EXISTS "clinician_licences" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Licence holder.
	"clinician_id" BIGINT NOT NULL,
	-- State or province the licence is valid in. One row per region, which is how multi-state practice is represented.
	"region_code" VARCHAR(8) NOT NULL,
	-- Number as issued by the board, quoted on prescriptions in that region.
	"licence_number" VARCHAR(60) NOT NULL,
	-- Start of validity.
	"issued_on" DATE NOT NULL,
	-- End of validity. Not nullable — every licence expires, and a booking made for a date after this must be refused.
	"expires_on" DATE NOT NULL,
	-- active | suspended | lapsed | surrendered. A suspended licence blocks booking immediately without deleting history.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- When the credentialing team last confirmed the licence with the board. Null means self-attested and not yet checked.
	"verified_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "clinician_licences" IS 'The rule that decides who may treat whom. Booking is a join: a clinician is offerable to a patient only if a row here matches the patient region, is active, and has not expired by the appointment date. Expired licences are kept because a past consultation was lawful under the licence in force then.';
COMMENT ON COLUMN "clinician_licences"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "clinician_licences"."clinician_id" IS 'Licence holder.';
COMMENT ON COLUMN "clinician_licences"."region_code" IS 'State or province the licence is valid in. One row per region, which is how multi-state practice is represented.';
COMMENT ON COLUMN "clinician_licences"."licence_number" IS 'Number as issued by the board, quoted on prescriptions in that region.';
COMMENT ON COLUMN "clinician_licences"."issued_on" IS 'Start of validity.';
COMMENT ON COLUMN "clinician_licences"."expires_on" IS 'End of validity. Not nullable — every licence expires, and a booking made for a date after this must be refused.';
COMMENT ON COLUMN "clinician_licences"."status" IS 'active | suspended | lapsed | surrendered. A suspended licence blocks booking immediately without deleting history.';
COMMENT ON COLUMN "clinician_licences"."verified_at" IS 'When the credentialing team last confirmed the licence with the board. Null means self-attested and not yet checked.';

CREATE UNIQUE INDEX "uq_licence_clinician_region_number"
ON "clinician_licences" ("clinician_id", "region_code", "licence_number");
CREATE INDEX "idx_licence_region_status_expiry"
ON "clinician_licences" ("region_code", "status", "expires_on");

CREATE TABLE IF NOT EXISTS "availability_slots" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Clinician offering the time.
	"clinician_id" BIGINT NOT NULL,
	-- Slot start as an instant. Cross-region scheduling makes local time useless as a storage format.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- Slot end. Stored rather than derived so a clinician can offer an unusual length.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- open | held | booked | cancelled. A hold is a soft lock taken while the patient completes payment.
	"status" VARCHAR(16) NOT NULL DEFAULT 'open',
	-- When a held slot returns to open. Null unless status is held; a sweeper releases anything past this instant.
	"hold_expires_at" TIMESTAMPTZ,
	-- video | phone | async. Async slots are review windows rather than live appointments.
	"visit_type" VARCHAR(24) NOT NULL DEFAULT 'video',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "availability_slots" IS 'Bookable inventory, generated ahead from a clinician rota. A slot carries no region of its own: eligibility is recomputed against the patient at search time, so one slot can be offered to patients in every region the clinician is licensed in.';
COMMENT ON COLUMN "availability_slots"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "availability_slots"."clinician_id" IS 'Clinician offering the time.';
COMMENT ON COLUMN "availability_slots"."starts_at" IS 'Slot start as an instant. Cross-region scheduling makes local time useless as a storage format.';
COMMENT ON COLUMN "availability_slots"."ends_at" IS 'Slot end. Stored rather than derived so a clinician can offer an unusual length.';
COMMENT ON COLUMN "availability_slots"."status" IS 'open | held | booked | cancelled. A hold is a soft lock taken while the patient completes payment.';
COMMENT ON COLUMN "availability_slots"."hold_expires_at" IS 'When a held slot returns to open. Null unless status is held; a sweeper releases anything past this instant.';
COMMENT ON COLUMN "availability_slots"."visit_type" IS 'video | phone | async. Async slots are review windows rather than live appointments.';

CREATE UNIQUE INDEX "uq_slot_clinician_start"
ON "availability_slots" ("clinician_id", "starts_at");
CREATE INDEX "idx_slot_status_start"
ON "availability_slots" ("status", "starts_at");

CREATE TABLE IF NOT EXISTS "consultations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient seen.
	"patient_id" BIGINT NOT NULL,
	-- Clinician who conducted the visit.
	"clinician_id" BIGINT NOT NULL,
	-- Slot consumed. Unique so one slot cannot be double-booked. Null for on-demand visits pulled straight from the waiting room.
	"slot_id" BIGINT UNIQUE,
	-- Patient region at the moment of booking, snapshotted. A later move must not retroactively make a past visit look unlicensed.
	"region_code" VARCHAR(8) NOT NULL,
	-- The licence the visit was conducted under, captured for audit. Null only for pre-launch records backfilled without one.
	"licence_id" BIGINT,
	-- video | phone | async.
	"visit_type" VARCHAR(24) NOT NULL DEFAULT 'video',
	-- scheduled | waiting | in_progress | completed | cancelled | no_show. no_show is kept because it drives both billing and panel management.
	"status" VARCHAR(24) NOT NULL DEFAULT 'scheduled',
	-- When the patient arrived in the virtual waiting room. The gap between this and started_at is the wait time patients complain about, so it is measured rather than estimated.
	"waiting_room_entered_at" TIMESTAMPTZ,
	-- When the clinician joined the call.
	"started_at" TIMESTAMPTZ,
	-- Call end. Null while in progress.
	"ended_at" TIMESTAMPTZ,
	-- Opaque room identifier at the video vendor. Stored so a session can be rejoined and so recordings can be reconciled.
	"video_room_ref" VARCHAR(120),
	-- Reason for the visit in the patient own words, captured at booking.
	"chief_complaint" VARCHAR(255),
	-- Amount charged, snapshotted from region_prices at booking. Prices change; a receipt must not.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency of price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Free text captured on cancellation, used to separate patient churn from clinician no-shows.
	"cancelled_reason" VARCHAR(255),
	-- Booking time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "consultations" IS 'One virtual visit, and the anchor for everything clinical. The region and licence are snapshotted here rather than joined at read time, which is what makes a retrospective compliance audit a single-table scan.';
COMMENT ON COLUMN "consultations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "consultations"."patient_id" IS 'Patient seen.';
COMMENT ON COLUMN "consultations"."clinician_id" IS 'Clinician who conducted the visit.';
COMMENT ON COLUMN "consultations"."slot_id" IS 'Slot consumed. Unique so one slot cannot be double-booked. Null for on-demand visits pulled straight from the waiting room.';
COMMENT ON COLUMN "consultations"."region_code" IS 'Patient region at the moment of booking, snapshotted. A later move must not retroactively make a past visit look unlicensed.';
COMMENT ON COLUMN "consultations"."licence_id" IS 'The licence the visit was conducted under, captured for audit. Null only for pre-launch records backfilled without one.';
COMMENT ON COLUMN "consultations"."visit_type" IS 'video | phone | async.';
COMMENT ON COLUMN "consultations"."status" IS 'scheduled | waiting | in_progress | completed | cancelled | no_show. no_show is kept because it drives both billing and panel management.';
COMMENT ON COLUMN "consultations"."waiting_room_entered_at" IS 'When the patient arrived in the virtual waiting room. The gap between this and started_at is the wait time patients complain about, so it is measured rather than estimated.';
COMMENT ON COLUMN "consultations"."started_at" IS 'When the clinician joined the call.';
COMMENT ON COLUMN "consultations"."ended_at" IS 'Call end. Null while in progress.';
COMMENT ON COLUMN "consultations"."video_room_ref" IS 'Opaque room identifier at the video vendor. Stored so a session can be rejoined and so recordings can be reconciled.';
COMMENT ON COLUMN "consultations"."chief_complaint" IS 'Reason for the visit in the patient own words, captured at booking.';
COMMENT ON COLUMN "consultations"."price_cents" IS 'Amount charged, snapshotted from region_prices at booking. Prices change; a receipt must not.';
COMMENT ON COLUMN "consultations"."currency_code" IS 'ISO 4217 currency of price_cents.';
COMMENT ON COLUMN "consultations"."cancelled_reason" IS 'Free text captured on cancellation, used to separate patient churn from clinician no-shows.';
COMMENT ON COLUMN "consultations"."created_at" IS 'Booking time.';

CREATE INDEX "idx_consultations_patient_created"
ON "consultations" ("patient_id", "created_at");
CREATE INDEX "idx_consultations_clinician_status"
ON "consultations" ("clinician_id", "status");

CREATE TABLE IF NOT EXISTS "intake_forms" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Form title shown to the patient, e.g. Dermatology intake.
	"name" VARCHAR(120) NOT NULL,
	-- Bumped on every wording change. Old versions are never edited, because an answer only means something next to the question that was asked.
	"version" INTEGER NOT NULL DEFAULT 1,
	-- Specialty this form is used for. Null for the universal pre-visit form.
	"specialty" VARCHAR(80),
	-- Question list with ids, types, options and branching. JSON because the shape changes weekly and no clinical query reads individual questions from here.
	"definition" JSONB NOT NULL,
	-- False retires a version without breaking responses that reference it.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "intake_forms" IS 'Versioned questionnaire templates. Keeping the definition as a document and the answers as a document avoids a migration every time the clinical team adds a question.';
COMMENT ON COLUMN "intake_forms"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "intake_forms"."name" IS 'Form title shown to the patient, e.g. Dermatology intake.';
COMMENT ON COLUMN "intake_forms"."version" IS 'Bumped on every wording change. Old versions are never edited, because an answer only means something next to the question that was asked.';
COMMENT ON COLUMN "intake_forms"."specialty" IS 'Specialty this form is used for. Null for the universal pre-visit form.';
COMMENT ON COLUMN "intake_forms"."definition" IS 'Question list with ids, types, options and branching. JSON because the shape changes weekly and no clinical query reads individual questions from here.';
COMMENT ON COLUMN "intake_forms"."is_active" IS 'False retires a version without breaking responses that reference it.';

CREATE UNIQUE INDEX "uq_intake_form_name_version"
ON "intake_forms" ("name", "version");

CREATE TABLE IF NOT EXISTS "intake_responses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Visit the intake was completed for.
	"consultation_id" BIGINT NOT NULL,
	-- Exact form version answered.
	"form_id" BIGINT NOT NULL,
	-- Answers keyed by the question ids in the form definition.
	"answers" JSONB NOT NULL,
	-- Comma-separated triage flags derived on submission, e.g. chest_pain. Denormalised so the waiting room can sort on it without opening the JSON.
	"red_flags" VARCHAR(255),
	-- Submission time. A consultation with no response here is the one the clinician starts blind.
	"submitted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "intake_responses" IS 'One completed questionnaire. Responses point at a specific form version so a question that was later reworded still reads correctly against the answer it produced.';
COMMENT ON COLUMN "intake_responses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "intake_responses"."consultation_id" IS 'Visit the intake was completed for.';
COMMENT ON COLUMN "intake_responses"."form_id" IS 'Exact form version answered.';
COMMENT ON COLUMN "intake_responses"."answers" IS 'Answers keyed by the question ids in the form definition.';
COMMENT ON COLUMN "intake_responses"."red_flags" IS 'Comma-separated triage flags derived on submission, e.g. chest_pain. Denormalised so the waiting room can sort on it without opening the JSON.';
COMMENT ON COLUMN "intake_responses"."submitted_at" IS 'Submission time. A consultation with no response here is the one the clinician starts blind.';

CREATE UNIQUE INDEX "uq_intake_response_consult_form"
ON "intake_responses" ("consultation_id", "form_id");

CREATE TABLE IF NOT EXISTS "clinical_notes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Visit documented.
	"consultation_id" BIGINT NOT NULL,
	-- Clinician who wrote the note.
	"author_id" BIGINT NOT NULL,
	-- What the patient reports.
	"subjective" TEXT,
	-- What the clinician observes, which on video is limited and deliberately recorded as such.
	"objective" TEXT,
	-- Diagnostic impression.
	"assessment" TEXT,
	-- Treatment plan, including anything prescribed or referred.
	"plan" TEXT,
	-- Signature time. Null means a draft, and a draft is not part of the legal record.
	"signed_at" TIMESTAMPTZ,
	-- Note this one corrects. Signed notes are never edited; an amendment is a new row pointing back, which is what keeps the chain auditable.
	"amends_note_id" BIGINT,
	-- Draft creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "clinical_notes" IS 'The clinical record of the visit, in SOAP sections. Amendment by self-reference rather than update is the difference between a record a regulator accepts and one it does not.';
COMMENT ON COLUMN "clinical_notes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "clinical_notes"."consultation_id" IS 'Visit documented.';
COMMENT ON COLUMN "clinical_notes"."author_id" IS 'Clinician who wrote the note.';
COMMENT ON COLUMN "clinical_notes"."subjective" IS 'What the patient reports.';
COMMENT ON COLUMN "clinical_notes"."objective" IS 'What the clinician observes, which on video is limited and deliberately recorded as such.';
COMMENT ON COLUMN "clinical_notes"."assessment" IS 'Diagnostic impression.';
COMMENT ON COLUMN "clinical_notes"."plan" IS 'Treatment plan, including anything prescribed or referred.';
COMMENT ON COLUMN "clinical_notes"."signed_at" IS 'Signature time. Null means a draft, and a draft is not part of the legal record.';
COMMENT ON COLUMN "clinical_notes"."amends_note_id" IS 'Note this one corrects. Signed notes are never edited; an amendment is a new row pointing back, which is what keeps the chain auditable.';
COMMENT ON COLUMN "clinical_notes"."created_at" IS 'Draft creation time.';

CREATE INDEX "idx_notes_consultation_created"
ON "clinical_notes" ("consultation_id", "created_at");

CREATE TABLE IF NOT EXISTS "pharmacies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Pharmacy identifier used by e-prescribing networks. Null for international pharmacies outside that scheme.
	"ncpdp_id" VARCHAR(20) UNIQUE,
	-- Trading name shown to the patient when they choose where to collect.
	"name" VARCHAR(160) NOT NULL,
	-- Region the pharmacy operates in, checked against the prescription.
	"region_code" VARCHAR(8) NOT NULL,
	-- Street address for the pickup instructions.
	"address_line" VARCHAR(255),
	-- Used when a prescription fails to transmit electronically.
	"phone" VARCHAR(32),
	-- False means the prescription has to be faxed, which changes the transmission path entirely.
	"accepts_erx" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pharmacies" IS 'Destination directory for prescriptions. Held locally rather than looked up live so that a routing failure can be diagnosed against the address that was actually used.';
COMMENT ON COLUMN "pharmacies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pharmacies"."ncpdp_id" IS 'Pharmacy identifier used by e-prescribing networks. Null for international pharmacies outside that scheme.';
COMMENT ON COLUMN "pharmacies"."name" IS 'Trading name shown to the patient when they choose where to collect.';
COMMENT ON COLUMN "pharmacies"."region_code" IS 'Region the pharmacy operates in, checked against the prescription.';
COMMENT ON COLUMN "pharmacies"."address_line" IS 'Street address for the pickup instructions.';
COMMENT ON COLUMN "pharmacies"."phone" IS 'Used when a prescription fails to transmit electronically.';
COMMENT ON COLUMN "pharmacies"."accepts_erx" IS 'False means the prescription has to be faxed, which changes the transmission path entirely.';

CREATE INDEX "idx_pharmacies_region_name"
ON "pharmacies" ("region_code", "name");

CREATE TABLE IF NOT EXISTS "e_prescriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Visit that produced the order. A prescription without a visit is not defensible.
	"consultation_id" BIGINT NOT NULL,
	-- Patient prescribed for. Denormalised from the consultation because the patient medication list is read far more often than the visit.
	"patient_id" BIGINT NOT NULL,
	-- Clinician who signed. Legally required, never null.
	"prescriber_id" BIGINT NOT NULL,
	-- Destination pharmacy. Null while the patient has not yet chosen one.
	"pharmacy_id" BIGINT,
	-- Drug as prescribed, including strength.
	"drug_name" VARCHAR(200) NOT NULL,
	-- RxNorm or equivalent code. Null for compounded items that have none.
	"drug_code" VARCHAR(24),
	-- Amount per administration.
	"dose" VARCHAR(60) NOT NULL,
	-- How often, e.g. twice daily.
	"frequency" VARCHAR(60) NOT NULL,
	-- Units to dispense.
	"quantity" INTEGER NOT NULL,
	-- Repeats permitted. Controlled substances are usually zero here.
	"refills_allowed" INTEGER NOT NULL DEFAULT 0,
	-- II to V where applicable. Null for non-controlled drugs. Drives identity checks and blocks some virtual-only prescribing.
	"controlled_schedule" VARCHAR(8),
	-- When the network accepted it. Null means it has not left the building.
	"transmitted_at" TIMESTAMPTZ,
	-- pending | sent | acknowledged | failed | cancelled. Failed prescriptions are retried, so the state has to live in a column rather than in a queue.
	"transmission_status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "e_prescriptions" IS 'A signed order routed to a pharmacy. Transmission state is modelled explicitly because the failure mode patients notice is a prescription that was written but never arrived.';
COMMENT ON COLUMN "e_prescriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "e_prescriptions"."consultation_id" IS 'Visit that produced the order. A prescription without a visit is not defensible.';
COMMENT ON COLUMN "e_prescriptions"."patient_id" IS 'Patient prescribed for. Denormalised from the consultation because the patient medication list is read far more often than the visit.';
COMMENT ON COLUMN "e_prescriptions"."prescriber_id" IS 'Clinician who signed. Legally required, never null.';
COMMENT ON COLUMN "e_prescriptions"."pharmacy_id" IS 'Destination pharmacy. Null while the patient has not yet chosen one.';
COMMENT ON COLUMN "e_prescriptions"."drug_name" IS 'Drug as prescribed, including strength.';
COMMENT ON COLUMN "e_prescriptions"."drug_code" IS 'RxNorm or equivalent code. Null for compounded items that have none.';
COMMENT ON COLUMN "e_prescriptions"."dose" IS 'Amount per administration.';
COMMENT ON COLUMN "e_prescriptions"."frequency" IS 'How often, e.g. twice daily.';
COMMENT ON COLUMN "e_prescriptions"."quantity" IS 'Units to dispense.';
COMMENT ON COLUMN "e_prescriptions"."refills_allowed" IS 'Repeats permitted. Controlled substances are usually zero here.';
COMMENT ON COLUMN "e_prescriptions"."controlled_schedule" IS 'II to V where applicable. Null for non-controlled drugs. Drives identity checks and blocks some virtual-only prescribing.';
COMMENT ON COLUMN "e_prescriptions"."transmitted_at" IS 'When the network accepted it. Null means it has not left the building.';
COMMENT ON COLUMN "e_prescriptions"."transmission_status" IS 'pending | sent | acknowledged | failed | cancelled. Failed prescriptions are retried, so the state has to live in a column rather than in a queue.';

CREATE INDEX "idx_erx_patient_transmitted"
ON "e_prescriptions" ("patient_id", "transmitted_at");
CREATE INDEX "idx_erx_consultation"
ON "e_prescriptions" ("consultation_id");

CREATE TABLE IF NOT EXISTS "follow_ups" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Visit that asked for the follow-up.
	"consultation_id" BIGINT NOT NULL,
	-- Patient to bring back.
	"patient_id" BIGINT NOT NULL,
	-- Local calendar date the follow-up is wanted by, not an instant — clinical intent is in days, not minutes.
	"due_on" DATE NOT NULL,
	-- Why, e.g. review blood pressure after two weeks on therapy.
	"reason" VARCHAR(255) NOT NULL,
	-- pending | scheduled | completed | declined | lapsed. lapsed is the state worth alerting on.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- The visit that satisfied it, closing the loop. Null until the patient books.
	"booked_consultation_id" BIGINT,
	-- When the clinician raised it.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "follow_ups" IS 'An open clinical loop. Modelled as its own row rather than a date on the consultation because the thing you need to query is every patient who was told to come back and has not.';
COMMENT ON COLUMN "follow_ups"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "follow_ups"."consultation_id" IS 'Visit that asked for the follow-up.';
COMMENT ON COLUMN "follow_ups"."patient_id" IS 'Patient to bring back.';
COMMENT ON COLUMN "follow_ups"."due_on" IS 'Local calendar date the follow-up is wanted by, not an instant — clinical intent is in days, not minutes.';
COMMENT ON COLUMN "follow_ups"."reason" IS 'Why, e.g. review blood pressure after two weeks on therapy.';
COMMENT ON COLUMN "follow_ups"."status" IS 'pending | scheduled | completed | declined | lapsed. lapsed is the state worth alerting on.';
COMMENT ON COLUMN "follow_ups"."booked_consultation_id" IS 'The visit that satisfied it, closing the loop. Null until the patient books.';
COMMENT ON COLUMN "follow_ups"."created_at" IS 'When the clinician raised it.';

CREATE INDEX "idx_followups_status_due"
ON "follow_ups" ("status", "due_on");

CREATE TABLE IF NOT EXISTS "region_prices" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Region the price applies in. Virtual care is priced per jurisdiction because the cost of practising in one is not the cost in another.
	"region_code" VARCHAR(8) NOT NULL,
	-- video | phone | async.
	"visit_type" VARCHAR(24) NOT NULL,
	-- Specialty the price applies to. Null is the default price for the region.
	"specialty" VARCHAR(80),
	-- Cash price in minor units.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- First day the price applies.
	"effective_from" DATE NOT NULL,
	-- Last day. Null while current. Rows are superseded rather than updated so an old receipt can still be explained.
	"effective_to" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "region_prices" IS 'The price book, keyed by region and visit type with validity dates. Consultations snapshot the amount, so this table is only ever read when quoting a new booking.';
COMMENT ON COLUMN "region_prices"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "region_prices"."region_code" IS 'Region the price applies in. Virtual care is priced per jurisdiction because the cost of practising in one is not the cost in another.';
COMMENT ON COLUMN "region_prices"."visit_type" IS 'video | phone | async.';
COMMENT ON COLUMN "region_prices"."specialty" IS 'Specialty the price applies to. Null is the default price for the region.';
COMMENT ON COLUMN "region_prices"."price_cents" IS 'Cash price in minor units.';
COMMENT ON COLUMN "region_prices"."currency_code" IS 'ISO 4217 currency.';
COMMENT ON COLUMN "region_prices"."effective_from" IS 'First day the price applies.';
COMMENT ON COLUMN "region_prices"."effective_to" IS 'Last day. Null while current. Rows are superseded rather than updated so an old receipt can still be explained.';

CREATE INDEX "idx_region_prices_lookup"
ON "region_prices" ("region_code", "visit_type", "effective_from");

CREATE TABLE IF NOT EXISTS "insurance_eligibility" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient checked.
	"patient_id" BIGINT NOT NULL,
	-- Insurer as named in the response.
	"payer_name" VARCHAR(160) NOT NULL,
	-- Membership identifier submitted in the check.
	"member_number" VARCHAR(60) NOT NULL,
	-- Region the plan covers, which is frequently not where the patient currently is.
	"plan_region_code" VARCHAR(8),
	-- eligible | inactive | not_covered | unknown. unknown is common and must be distinguishable from a refusal.
	"status" VARCHAR(24) NOT NULL,
	-- Patient copay quoted by the payer, in minor units. Null when the payer returns no benefit detail.
	"copay_cents" INTEGER,
	-- Remaining deductible at check time. Goes stale within days, which is why checked_at matters.
	"deductible_remaining_cents" INTEGER,
	-- When the check ran.
	"checked_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the platform stops trusting this answer and re-checks.
	"expires_at" TIMESTAMPTZ,
	-- Raw payer response, kept verbatim to settle disputes about what was quoted.
	"response_payload" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "insurance_eligibility" IS 'A point-in-time answer from a payer, not a standing fact. Every check is a new row because eligibility is a moving target and the only defensible claim is what the payer said at the moment of booking.';
COMMENT ON COLUMN "insurance_eligibility"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "insurance_eligibility"."patient_id" IS 'Patient checked.';
COMMENT ON COLUMN "insurance_eligibility"."payer_name" IS 'Insurer as named in the response.';
COMMENT ON COLUMN "insurance_eligibility"."member_number" IS 'Membership identifier submitted in the check.';
COMMENT ON COLUMN "insurance_eligibility"."plan_region_code" IS 'Region the plan covers, which is frequently not where the patient currently is.';
COMMENT ON COLUMN "insurance_eligibility"."status" IS 'eligible | inactive | not_covered | unknown. unknown is common and must be distinguishable from a refusal.';
COMMENT ON COLUMN "insurance_eligibility"."copay_cents" IS 'Patient copay quoted by the payer, in minor units. Null when the payer returns no benefit detail.';
COMMENT ON COLUMN "insurance_eligibility"."deductible_remaining_cents" IS 'Remaining deductible at check time. Goes stale within days, which is why checked_at matters.';
COMMENT ON COLUMN "insurance_eligibility"."checked_at" IS 'When the check ran.';
COMMENT ON COLUMN "insurance_eligibility"."expires_at" IS 'When the platform stops trusting this answer and re-checks.';
COMMENT ON COLUMN "insurance_eligibility"."response_payload" IS 'Raw payer response, kept verbatim to settle disputes about what was quoted.';

CREATE INDEX "idx_eligibility_patient_checked"
ON "insurance_eligibility" ("patient_id", "checked_at");

